-- privacy.dataStorage
('privacy.dataStorage.title', 'en', 'Data Storage'),
('privacy.dataStorage.title', 'hr', 'Pohrana podataka'),
('privacy.dataStorage.title', 'it', 'Archiviazione dati'),
('privacy.dataStorage.title', 'de', 'Datenspeicherung'),
('privacy.dataStorage.text', 'en', 'This website does not store personal data on its servers. Any data you provide via email is handled through your email provider and ours. We do not maintain databases of visitor information.'),
('privacy.dataStorage.text', 'hr', 'Ova web stranica ne pohranjuje osobne podatke na svojim serverima. Svi podaci koje pružite putem e-pošte obrađuju se putem vašeg i našeg pružatelja e-pošte. Ne održavamo baze podataka informacija o posjetiteljima.'),
('privacy.dataStorage.text', 'it', 'Questo sito web non memorizza dati personali sui propri server. Qualsiasi dato fornito via email viene gestito dal tuo provider email e dal nostro. Non manteniamo database di informazioni sui visitatori.'),
('privacy.dataStorage.text', 'de', 'Diese Website speichert keine persönlichen Daten auf ihren Servern. Alle Daten, die Sie per E-Mail bereitstellen, werden über Ihren und unseren E-Mail-Anbieter verarbeitet. Wir führen keine Datenbanken mit Besucherinformationen.'),
