-- privacy.gdprRights
('privacy.gdprRights.title', 'en', 'Your Rights Under GDPR'),
('privacy.gdprRights.title', 'hr', 'Vaša prava prema GDPR-u'),
('privacy.gdprRights.title', 'it', 'I tuoi diritti secondo il GDPR'),
('privacy.gdprRights.title', 'de', 'Ihre Rechte nach DSGVO'),
('privacy.gdprRights.text', 'en', 'Under the General Data Protection Regulation (GDPR), you have the following rights:'),
('privacy.gdprRights.text', 'hr', 'Prema Općoj uredbi o zaštiti podataka (GDPR), imate sljedeća prava:'),
('privacy.gdprRights.text', 'it', 'Ai sensi del Regolamento Generale sulla Protezione dei Dati (GDPR), hai i seguenti diritti:'),
('privacy.gdprRights.text', 'de', 'Gemäß der Datenschutz-Grundverordnung (DSGVO) haben Sie folgende Rechte:'),
('privacy.gdprRights.item1', 'en', 'Right of access - to request copies of your personal data'),
('privacy.gdprRights.item1', 'hr', 'Pravo pristupa - zatražiti kopije vaših osobnih podataka'),
('privacy.gdprRights.item1', 'it', 'Diritto di accesso - richiedere copie dei tuoi dati personali'),
('privacy.gdprRights.item1', 'de', 'Auskunftsrecht - Kopien Ihrer persönlichen Daten anzufordern'),
('privacy.gdprRights.item2', 'en', 'Right to rectification - to request correction of inaccurate data'),
('privacy.gdprRights.item2', 'hr', 'Pravo na ispravak - zatražiti ispravak netočnih podataka'),
('privacy.gdprRights.item2', 'it', 'Diritto di rettifica - richiedere la correzione di dati inesatti'),
('privacy.gdprRights.item2', 'de', 'Recht auf Berichtigung - Korrektur unrichtiger Daten zu verlangen'),
('privacy.gdprRights.item3', 'en', 'Right to erasure - to request deletion of your data'),
('privacy.gdprRights.item3', 'hr', 'Pravo na brisanje - zatražiti brisanje vaših podataka'),
('privacy.gdprRights.item3', 'it', 'Diritto alla cancellazione - richiedere la cancellazione dei tuoi dati'),
('privacy.gdprRights.item3', 'de', 'Recht auf Löschung - Löschung Ihrer Daten zu verlangen'),
('privacy.gdprRights.item4', 'en', 'Right to restrict processing - to limit how we use your data'),
('privacy.gdprRights.item4', 'hr', 'Pravo na ograničenje obrade - ograničiti kako koristimo vaše podatke'),
('privacy.gdprRights.item4', 'it', 'Diritto di limitare il trattamento - limitare come utilizziamo i tuoi dati'),
('privacy.gdprRights.item4', 'de', 'Recht auf Einschränkung der Verarbeitung - zu beschränken, wie wir Ihre Daten verwenden'),
('privacy.gdprRights.item5', 'en', 'Right to object - to object to the processing of your data'),
('privacy.gdprRights.item5', 'hr', 'Pravo na prigovor - prigovoriti obradi vaših podataka'),
('privacy.gdprRights.item5', 'it', 'Diritto di opposizione - opporsi al trattamento dei tuoi dati'),
('privacy.gdprRights.item5', 'de', 'Widerspruchsrecht - der Verarbeitung Ihrer Daten zu widersprechen'),
