('cookie.title', 'de', 'Cookie-Richtlinie'),
('cookie.intro', 'en', 'This Cookie Policy explains how Villa Palazzina Burjaki uses cookies and similar technologies on this website.'),
('cookie.intro', 'hr', 'Ova politika kolačića objašnjava kako Villa Palazzina Burjaki koristi kolačiće i slične tehnologije na ovoj web stranici.'),
('cookie.intro', 'it', 'Questa politica sui cookie spiega come Villa Palazzina Burjaki utilizza i cookie e tecnologie simili su questo sito web.'),
('cookie.intro', 'de', 'Diese Cookie-Richtlinie erklärt, wie Villa Palazzina Burjaki Cookies und ähnliche Technologien auf dieser Website verwendet.'),
('cookie.whatAreCookies.title', 'en', 'What Are Cookies?'),
('cookie.whatAreCookies.title', 'hr', 'Što su kolačići?'),
('cookie.whatAreCookies.title', 'it', 'Cosa sono i cookie?'),
('cookie.whatAreCookies.title', 'de', 'Was sind Cookies?'),
('cookie.whatAreCookies.text', 'en', 'Cookies are small text files that are stored on your device when you visit a website. They help websites function properly and provide information to website owners.'),
('cookie.whatAreCookies.text', 'hr', 'Kolačići su male tekstualne datoteke koje se pohranjuju na vašem uređaju kada posjetite web stranicu. Pomažu web stranicama da pravilno funkcioniraju i pružaju informacije vlasnicima web stranica.'),
('cookie.whatAreCookies.text', 'it', 'I cookie sono piccoli file di testo che vengono memorizzati sul tuo dispositivo quando visiti un sito web. Aiutano i siti web a funzionare correttamente e forniscono informazioni ai proprietari dei siti.'),
('cookie.whatAreCookies.text', 'de', 'Cookies sind kleine Textdateien, die auf Ihrem Gerät gespeichert werden, wenn Sie eine Website besuchen. Sie helfen Websites, ordnungsgemäß zu funktionieren, und liefern Informationen an Website-Betreiber.'),
